import { readFileSync, realpathSync, statSync } from 'node:fs';
import { createRequire } from 'node:module';
import path from 'node:path';

export function isCodexLookup(command) {
    return /^codex(?:\.(?:exe|com|cmd|bat|ps1))?$/i.test(path.win32.basename(command));
}

const file = name => { try { return statSync(name).isFile(); } catch { return false; } };
const canonical = name => { try { return realpathSync(name); } catch { return name; } };

/** Never let a desktop-injected PATH select the GUI or its private CLI. */
export function isCodexDesktopBinary(filename) {
    const names = [filename, canonical(filename)].map(value => value.replaceAll('\\', '/'));
    return names.some(name => {
        if (/\/OpenAI\.Codex(?:PrimaryRuntime)?_[^/]+\//i.test(name) || /\/Codex\.app\/Contents\//i.test(name) || /\/packages\/app-server-daemon\//i.test(name)) return true;
        const directory = path.dirname(name);
        return file(path.join(directory, 'resources', 'app.asar')) ||
            (file(path.join(directory, 'resources.pak')) && file(path.join(directory, 'icudtl.dat'))) ||
            (/\/resources\/codex(?:\.exe)?$/i.test(name) &&
                (file(path.join(directory, 'app.asar')) || file(path.join(directory, '..', 'Codex.exe'))));
    });
}

/** Check recognized npm shims without executing package code or opening a UI. */
export function isCodexCliCandidate(filename) {
    if (isCodexDesktopBinary(filename)) return false;
    // npm also emits a PowerShell shim; prefer its .cmd sibling so execution
    // does not depend on the user's PowerShell execution policy.
    if (/\.ps1$/i.test(filename)) return false;
    if (!/\.(?:cmd|bat)$/i.test(filename)) return true;
    let shim;
    try { shim = readFileSync(filename, 'utf8'); } catch { return false; }
    const relative = /"%dp0%[\\/]([^"\r\n]*@openai[\\/]codex[\\/]bin[\\/]codex\.js)"/i.exec(shim)?.[1];
    // Custom launchers stay supported; validate the target of npm's known shim.
    if (!relative) return !/@openai[\\/]codex[\\/]bin[\\/]codex\.js/i.test(shim);
    const script = path.win32.resolve(path.win32.dirname(filename), relative);
    if (!file(script)) return false;
    try {
        const root = path.dirname(path.dirname(canonical(script)));
        const manifest = JSON.parse(readFileSync(path.join(root, 'package.json'), 'utf8'));
        const packageName = `@openai/codex-${process.platform}-${process.arch}`;
        if (!manifest.optionalDependencies?.[packageName]) return true;
        const triple = process.platform === 'win32' ? (process.arch === 'arm64' ? 'aarch64' : 'x86_64') + '-pc-windows-msvc' : undefined;
        if (!triple) return true;
        let vendor;
        try { vendor = path.join(path.dirname(createRequire(script).resolve(packageName + '/package.json')), 'vendor'); }
        catch { vendor = path.join(root, 'vendor'); }
        return ['bin', 'codex'].some(directory => file(path.join(vendor, triple, directory, 'codex.exe')));
    } catch { return false; }
}

export function cliShellCommand(executable, args = [], platform = process.platform) {
    if (platform === 'win32') {
        const literal = value => {
            if (/[\r\n\0"]/.test(value)) throw new Error('Invalid Windows CLI argument');
            return "'" + value.replaceAll("'", "''") + "'";
        };
        const selected = literal(executable);
        const arguments_ = args.map(literal);
        const script = [
            "$ErrorActionPreference = 'Stop'",
            'try {',
            `$cli = ${selected}`,
            /\.(?:cmd|bat)$/i.test(executable)
                ? [
                    '$env:CARB_SELECTED_CLI = $cli',
                    ...arguments_.map((argument, index) => `$env:CARB_SELECTED_CLI_ARG_${index} = ${argument}`),
                    // cmd expands each variable once. A literal %NAME% in a
                    // selected path or argument must not be expanded again.
                    "& $env:ComSpec /d /v:off /s /c '" +
                        ['"%CARB_SELECTED_CLI%"', ...args.map((argument, index) => argument === '' ? '""' : `"%CARB_SELECTED_CLI_ARG_${index}%"`)].join(' ') + "'",
                ].join('; ')
                : `& $cli${arguments_.length ? ' ' + arguments_.map((argument, index) => args[index] === '' ? "'\"\"'" : argument).join(' ') : ''}`,
            'if ($null -ne $LASTEXITCODE) { exit $LASTEXITCODE }',
            'exit 0',
            '} catch {',
            "Write-Host ('Codex CLI could not start: ' + $_.Exception.Message) -ForegroundColor Red",
            'exit 1',
            '}',
        ].join('; ');
        // node-pty quotes the complete cmd /c argument using Win32 argv rules.
        // Keep quotes out of that argument; PowerShell decodes the exact path
        // and arguments in its own process and leaves its console interactive.
        return 'powershell.exe -NoLogo -NoProfile -ExecutionPolicy Bypass -EncodedCommand ' + Buffer.from(script, 'utf16le').toString('base64');
    }
    const quote = value => "'" + value.replaceAll("'", "'\\''") + "'";
    return [quote(executable), ...args.map(quote)].join(' ');
}
